// Biruni GIS launcher: starts the bundled QGIS engine with the Biruni profile,
// settings and shell plugin, and shows the splash screen until the main window
// is up. Built with the .NET Framework C# compiler (see scripts\build.ps1).
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.IO;
using System.Runtime.InteropServices;
using System.Text;
using System.Windows.Forms;

// Assembly metadata (version etc.) is generated by scripts\build.ps1.

namespace Biruni
{
    static class Launcher
    {
        const string AppName = "Biruni GIS";

        [STAThread]
        static int Main(string[] args)
        {
            try
            {
                return Run(args);
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message, AppName, MessageBoxButtons.OK, MessageBoxIcon.Error);
                return 1;
            }
        }

        static int Run(string[] args)
        {
            string exe = Application.ExecutablePath;
            string root = Path.GetDirectoryName(exe);
            string engine = Path.Combine(root, "engine");
            string app = Path.Combine(root, "app");

            // Development layout: biruni-dev.ini next to the exe points elsewhere.
            string devIni = Path.Combine(root, "biruni-dev.ini");
            if (File.Exists(devIni))
            {
                foreach (string raw in File.ReadAllLines(devIni))
                {
                    string line = raw.Trim();
                    int eq = line.IndexOf('=');
                    if (line.StartsWith(";") || eq < 0) continue;
                    string key = line.Substring(0, eq).Trim().ToLowerInvariant();
                    string val = line.Substring(eq + 1).Trim();
                    if (key == "engine") engine = val;
                    else if (key == "app") app = val;
                }
            }

            string qgis = Path.Combine(engine, "bin", "qgis-bin.exe");
            if (!File.Exists(qgis))
                throw new Exception("The Biruni GIS engine was not found:\n" + qgis + "\n\nPlease reinstall Biruni GIS.");
            EnsureEngine(engine, app);

            string profiles = Environment.GetEnvironmentVariable("BIRUNI_PROFILES_PATH");
            if (string.IsNullOrEmpty(profiles))
                profiles = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), AppName);
            Directory.CreateDirectory(profiles);

            var psi = new ProcessStartInfo(qgis);
            psi.UseShellExecute = false;
            psi.WorkingDirectory = Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments);
            psi.EnvironmentVariables["QGIS_PLUGINPATH"] = Path.Combine(app, "plugins");
            psi.EnvironmentVariables["BIRUNI_HOME"] = app;
            psi.EnvironmentVariables["BIRUNI_ROOT"] = root;
            psi.EnvironmentVariables["BIRUNI_LAUNCHER"] = exe;

            var qargs = new List<string> {
                "--profiles-path", profiles,
                "--globalsettingsfile", Path.Combine(app, "config", "qgis_global_settings.ini"),
                "--nologo", "--noversioncheck",
                "--code", Path.Combine(app, "boot", "biruni_boot.py"),
            };
            qargs.AddRange(args);
            psi.Arguments = JoinArgs(qargs);

            Process proc = Process.Start(psi);
            if (string.IsNullOrEmpty(Environment.GetEnvironmentVariable("BIRUNI_NO_SPLASH")))
            {
                Application.EnableVisualStyles();
                string splash = Path.Combine(app, "plugins", "biruni", "resources", "branding", "splash.png");
                Application.Run(new Splash(splash, proc));
            }
            return 0;
        }

        // The engine's bin\qgis-bin.env holds absolute paths written at install
        // time. Regenerate it when missing or when the folder was moved.
        static void EnsureEngine(string engine, string app)
        {
            if (EnvMatches(engine)) return;
            string script = Path.Combine(app, "scripts", "engine-postinstall.bat");
            if (!File.Exists(script))
                throw new Exception("The Biruni GIS engine is not configured and the setup script is missing:\n" + script);
            var psi = new ProcessStartInfo("cmd.exe", "/c \"\"" + script + "\" \"" + engine + "\"\"");
            psi.UseShellExecute = false;
            psi.CreateNoWindow = true;
            using (var p = Process.Start(psi)) p.WaitForExit();
            if (!EnvMatches(engine))
                throw new Exception("Biruni GIS could not prepare its engine in\n" + engine +
                                    "\n\nRun Biruni GIS once as administrator, or reinstall it.");
        }

        static bool EnvMatches(string engine)
        {
            string env = Path.Combine(engine, "bin", "qgis-bin.env");
            if (!File.Exists(env)) return false;
            foreach (string line in File.ReadAllLines(env))
            {
                if (!line.StartsWith("OSGEO4W_ROOT=", StringComparison.OrdinalIgnoreCase)) continue;
                string recorded = LongPath(line.Substring("OSGEO4W_ROOT=".Length).Trim());
                return string.Equals(recorded.TrimEnd('\\'), LongPath(engine).TrimEnd('\\'),
                                     StringComparison.OrdinalIgnoreCase);
            }
            return false;
        }

        [DllImport("kernel32.dll", CharSet = CharSet.Unicode)]
        static extern uint GetLongPathName(string shortPath, StringBuilder longPath, uint bufferSize);

        static string LongPath(string path)
        {
            try
            {
                path = Path.GetFullPath(path);
                var sb = new StringBuilder(1024);
                uint n = GetLongPathName(path, sb, (uint)sb.Capacity);
                return n > 0 && n < sb.Capacity ? sb.ToString() : path;
            }
            catch
            {
                return path;
            }
        }

        // Windows command-line quoting (CommandLineToArgvW rules).
        static string JoinArgs(IEnumerable<string> args)
        {
            var sb = new StringBuilder();
            foreach (string a in args)
            {
                if (sb.Length > 0) sb.Append(' ');
                if (a.Length > 0 && a.IndexOfAny(new[] { ' ', '\t', '"' }) < 0)
                {
                    sb.Append(a);
                    continue;
                }
                sb.Append('"');
                int backslashes = 0;
                foreach (char c in a)
                {
                    if (c == '\\') { backslashes++; continue; }
                    if (c == '"') { sb.Append('\\', backslashes * 2 + 1); sb.Append('"'); }
                    else { sb.Append('\\', backslashes); sb.Append(c); }
                    backslashes = 0;
                }
                sb.Append('\\', backslashes * 2);
                sb.Append('"');
            }
            return sb.ToString();
        }
    }

    class Splash : Form
    {
        [DllImport("user32.dll")]
        static extern bool IsWindowVisible(IntPtr hWnd);

        [DllImport("dwmapi.dll")]
        static extern int DwmSetWindowAttribute(IntPtr hwnd, int attr, ref int value, int size);

        readonly Image image;
        readonly Process proc;
        readonly Timer timer = new Timer();
        readonly DateTime started = DateTime.Now;
        int tick;
        int visibleTicks;

        public Splash(string imagePath, Process proc)
        {
            this.proc = proc;
            if (File.Exists(imagePath)) image = Image.FromFile(imagePath);
            FormBorderStyle = FormBorderStyle.None;
            StartPosition = FormStartPosition.CenterScreen;
            ShowInTaskbar = true;
            Text = "Biruni GIS";
            try { Icon = Icon.ExtractAssociatedIcon(Application.ExecutablePath); } catch { }
            DoubleBuffered = true;
            BackColor = Color.FromArgb(7, 40, 42);
            float scale = DeviceDpi / 96f;
            ClientSize = new Size((int)(600 * scale), (int)(350 * scale));
            timer.Interval = 30;
            timer.Tick += OnTick;
        }

        protected override void OnShown(EventArgs e)
        {
            base.OnShown(e);
            try
            {
                int round = 2; // DWMWCP_ROUND (Windows 11)
                DwmSetWindowAttribute(Handle, 33, ref round, sizeof(int));
            }
            catch { }
            timer.Start();
        }

        void OnTick(object sender, EventArgs e)
        {
            tick++;
            Invalidate();
            if (tick % 5 != 0) return;
            try
            {
                if (proc.HasExited)
                {
                    timer.Stop();
                    if (proc.ExitCode != 0 && (DateTime.Now - started).TotalSeconds < 120)
                        MessageBox.Show("Biruni GIS stopped while starting (exit code " + proc.ExitCode + ").",
                                        "Biruni GIS", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    Close();
                    return;
                }
                proc.Refresh();
                IntPtr h = proc.MainWindowHandle;
                if (h != IntPtr.Zero && IsWindowVisible(h)) visibleTicks++;
                if (visibleTicks >= 3 || (DateTime.Now - started).TotalSeconds > 180)
                {
                    timer.Stop();
                    Close();
                }
            }
            catch
            {
                timer.Stop();
                Close();
            }
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.InterpolationMode = InterpolationMode.HighQualityBicubic;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            if (image != null) g.DrawImage(image, ClientRectangle);
            // indeterminate progress line along the bottom edge
            int w = ClientSize.Width, h = Math.Max(3, (int)(3 * DeviceDpi / 96f));
            int seg = w / 4;
            int x = (tick * Math.Max(4, w / 120)) % (w + seg) - seg;
            using (var b = new SolidBrush(Color.FromArgb(70, 255, 255, 255)))
                g.FillRectangle(b, 0, ClientSize.Height - h, w, h);
            using (var b = new SolidBrush(Color.FromArgb(251, 191, 36)))
                g.FillRectangle(b, x, ClientSize.Height - h, seg, h);
        }

        protected override void Dispose(bool disposing)
        {
            if (disposing)
            {
                timer.Dispose();
                if (image != null) image.Dispose();
            }
            base.Dispose(disposing);
        }
    }
}
